    public Object parseMarket(Object market)
    {
        Object id = this.safeString(market, "instId");
        Object type = this.safeStringLower(market, "instType");
        Object spot = (Helpers.isEqual(type, "spot"));
        Object future = (Helpers.isEqual(type, "future"));
        Object swap = (Helpers.isEqual(type, "swap"));
        Object option = (Helpers.isEqual(type, "option"));
        Object contract = Helpers.isTrue(swap) || Helpers.isTrue(future);
        Object baseId = this.safeString(market, "baseCurrency");
        Object quoteId = this.safeString(market, "quoteCurrency");
        Object settleId = this.safeString(market, "settleCurrency", quoteId);
        Object settle = this.safeCurrencyCode(settleId);
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        if (Helpers.isTrue(swap))
        {
            symbol = Helpers.add(Helpers.add(symbol, ":"), settle);
        }
        Object expiry = null;
        Object strikePrice = null;
        Object optionType = null;
        Object tickSize = this.safeString(market, "tickSize");
        Object fees = this.safeDict2(this.fees, type, "trading", new java.util.HashMap<String, Object>() {{}});
        Object taker = this.safeNumber(fees, "taker");
        Object maker = this.safeNumber(fees, "maker");
        Object maxLeverage = this.safeString(market, "maxLeverage", "100");
        maxLeverage = Precise.stringMax(maxLeverage, "1");
        Object isActive = (Helpers.isEqual(this.safeString(market, "state"), "live"));
        Object isMargin = Helpers.isTrue(spot) && Helpers.isTrue((Precise.stringGt(maxLeverage, "1")));
        Object contractType = this.safeString(market, "contractType");
        Object maxLimitAmount = this.safeNumber(market, "maxLimitSize");
        Object maxSpotCost = this.safeNumber(market, "maxMarketSize"); // for spot, market-buy size is denominated in the quote currency, i.e. cost
        final Object finalSymbol = symbol;
        final Object finalBase = base;
        final Object finalType = type;
        final Object finalSpot = spot;
        final Object finalSwap = swap;
        final Object finalContractType = contractType;
        final Object finalMaxLeverage = maxLeverage;
        return this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "symbol", finalSymbol );
            put( "base", finalBase );
            put( "quote", quote );
            put( "baseId", baseId );
            put( "quoteId", quoteId );
            put( "settle", settle );
            put( "settleId", settleId );
            put( "type", finalType );
            put( "spot", finalSpot );
            put( "option", option );
            put( "margin", isMargin );
            put( "swap", finalSwap );
            put( "future", future );
            put( "active", isActive );
            put( "taker", taker );
            put( "maker", maker );
            put( "contract", contract );
            put( "linear", ((Helpers.isTrue(contract))) ? (Helpers.isEqual(finalContractType, "linear")) : null );
            put( "inverse", ((Helpers.isTrue(contract))) ? (Helpers.isEqual(finalContractType, "inverse")) : null );
            put( "contractSize", ((Helpers.isTrue(contract))) ? Blofin.this.safeNumber(market, "contractValue") : null );
            put( "expiry", expiry );
            put( "expiryDatetime", expiry );
            put( "strike", strikePrice );
            put( "optionType", optionType );
            put( "created", Blofin.this.safeInteger(market, "listTime") );
            put( "precision", new java.util.HashMap<String, Object>() {{
                put( "amount", Blofin.this.safeNumber(market, "lotSize") );
                put( "price", Blofin.this.parseNumber(tickSize) );
            }} );
            put( "limits", new java.util.HashMap<String, Object>() {{
                put( "leverage", new java.util.HashMap<String, Object>() {{
                    put( "min", Blofin.this.parseNumber("1") );
                    put( "max", Blofin.this.parseNumber(finalMaxLeverage) );
                }} );
                put( "amount", new java.util.HashMap<String, Object>() {{
                    put( "min", Blofin.this.safeNumber(market, "minSize") );
                    put( "max", maxLimitAmount );
                }} );
                put( "price", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "cost", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", ((Helpers.isTrue(contract))) ? null : maxSpotCost );
                }} );
            }} );
            put( "info", market );
        }});
    }

