    public Object parseTransaction(Object transaction, Object... optionalArgs)
    {
        //
        //
        // fetchDeposits
        //
        //     {
        //         "currency": "USDT",
        //         "chain": "TRC20",
        //         "address": "TGfJLtnsh3B9EqekFEBZ1nR14QanBUf5Be",
        //         "txId": "892f4e0c32268b29b2e541ef30d32a30bbf10f902adcc4b1428319ed7c3758fd",
        //         "type": "0",
        //         "amount": "86.975843",
        //         "state": "1",
        //         "ts": "1703163304153",
        //         "tag": null,
        //         "confirm": "16",
        //         "depositId": "36c8e2a7ea184a219de72215a696acaf"
        //     }
        // fetchWithdrawals
        //    {
        //       "currency": "USDT",
        //        "chain": "TRC20",
        //        "address": "TYgB3sVXHPEDQUu288EG1uMFh9Pk2swLgW",
        //        "txId": "1fd5ac52df414d7ea66194cadd9a5b4d2422c2b9720037f66d98207f9858fd96",
        //        "type": "0",
        //        "amount": "9",
        //        "fee": "1",
        //        "feeCurrency": "USDT",
        //        "state": "3",
        //        "clientId": null,
        //        "ts": "1707217439351",
        //        "tag": null,
        //        "memo": null,
        //        "withdrawId": "e0768698cfdf4aee8e54654c3775914b"
        //    }
        //
        Object currency = Helpers.getArg(optionalArgs, 0, null);
        Object type = null;
        Object id = null;
        Object status = null;
        Object withdrawalId = this.safeString(transaction, "withdrawId");
        Object depositId = this.safeString(transaction, "depositId");
        Object addressTo = this.safeString(transaction, "address");
        Object address = addressTo;
        Object tagTo = this.safeString(transaction, "tag");
        if (Helpers.isTrue(!Helpers.isEqual(withdrawalId, null)))
        {
            type = "withdrawal";
            id = withdrawalId;
            status = this.parseTransactionWithdrawalStatus(this.safeString(transaction, "state"));
        } else
        {
            id = depositId;
            type = "deposit";
            status = this.parseTransactionDepositStatus(this.safeString(transaction, "state"));
        }
        Object currencyId = this.safeString(transaction, "currency");
        Object code = this.safeCurrencyCode(currencyId);
        Object amount = this.safeNumber(transaction, "amount");
        Object txid = this.safeString(transaction, "txId");
        Object timestamp = this.safeInteger(transaction, "ts");
        Object feeCurrencyId = this.safeString(transaction, "feeCurrency");
        Object feeCode = this.safeCurrencyCode(feeCurrencyId);
        Object feeCost = this.safeNumber(transaction, "fee");
        final Object finalId = id;
        final Object finalStatus = status;
        final Object finalType = type;
        return new java.util.HashMap<String, Object>() {{
            put( "info", transaction );
            put( "id", finalId );
            put( "currency", code );
            put( "amount", amount );
            put( "network", null );
            put( "addressFrom", null );
            put( "addressTo", addressTo );
            put( "address", address );
            put( "tagFrom", null );
            put( "tagTo", tagTo );
            put( "tag", tagTo );
            put( "status", finalStatus );
            put( "type", finalType );
            put( "updated", null );
            put( "txid", txid );
            put( "timestamp", timestamp );
            put( "datetime", Blofin.this.iso8601(timestamp) );
            put( "internal", null );
            put( "comment", null );
            put( "fee", new java.util.HashMap<String, Object>() {{
                put( "currency", feeCode );
                put( "cost", feeCost );
            }} );
        }};
    }

    public Object parseTransactionWithdrawalStatus(Object status)
    {
        Object statuses = new java.util.HashMap<String, Object>() {{
            put( "0", "pending" );
            put( "2", "failed" );
            put( "3", "ok" );
            put( "4", "failed" );
            put( "6", "pending" );
            put( "7", "pending" );
        }};
        return this.safeString(statuses, status, status);
    }

    public Object parseTransactionDepositStatus(Object status)
    {
        Object statuses = new java.util.HashMap<String, Object>() {{
            put( "0", "pending" );
            put( "1", "ok" );
            put( "2", "failed" );
            put( "3", "pending" );
        }};
        return this.safeString(statuses, status, status);
    }

    public Object parseLedgerEntryType(Object type)
    {
        Object types = new java.util.HashMap<String, Object>() {{
            put( "1", "transfer" );
            put( "2", "trade" );
            put( "3", "trade" );
            put( "4", "rebate" );
            put( "5", "trade" );
            put( "6", "transfer" );
            put( "7", "trade" );
            put( "8", "fee" );
            put( "9", "trade" );
            put( "10", "trade" );
            put( "11", "trade" );
        }};
        return this.safeString(types, ((String)type), type);
    }

    public Object parseLedgerEntry(Object item, Object... optionalArgs)
    {
        Object currency = Helpers.getArg(optionalArgs, 0, null);
        Object currencyId = this.safeString(item, "currency");
        Object code = this.safeCurrencyCode(currencyId, currency);
        currency = this.safeCurrency(currencyId, currency);
        Object timestamp = this.safeInteger(item, "ts");
        return this.safeLedgerEntry(new java.util.HashMap<String, Object>() {{
            put( "info", item );
            put( "id", Blofin.this.safeString(item, "transferId") );
            put( "direction", null );
            put( "account", null );
            put( "referenceId", Blofin.this.safeString(item, "clientId") );
            put( "referenceAccount", null );
            put( "type", Blofin.this.parseLedgerEntryType(Blofin.this.safeString(item, "type")) );
            put( "currency", code );
            put( "amount", Blofin.this.safeNumber(item, "amount") );
            put( "timestamp", timestamp );
            put( "datetime", Blofin.this.iso8601(timestamp) );
            put( "before", null );
            put( "after", null );
            put( "status", "ok" );
            put( "fee", null );
        }}, currency);
    }

